(function(root){
'use strict';
function hero(data,C){const E=C.escape,featured=data.articles.find(a=>a.featured)||data.articles[0],ai=data.articles.find(a=>a.category==='ai')||featured,art=C.image(data.config.heroImage,400000)||'assets/horizon-portal.webp',first=data.categories[0],second=data.categories[1]||first;return `<section class="horizon-hero" id="trang-chu"><div class="horizon-hero-grid" aria-hidden="true"></div><div class="container horizon-hero-layout"><div class="horizon-copy"><div class="eyebrow horizon-kicker"><span class="live-dot"></span>TECH HORIZON / MỘT GÓC NHÌN MỚI</div><h1>Hiểu công nghệ.<br><span>Mở rộng<br>góc nhìn.</span><i aria-hidden="true">↗</i></h1><p data-exp-description>${E(data.config.description)}</p><div class="horizon-actions"><a class="button button-blue" href="#diem-bat-dau">Tìm bài dành cho bạn <span aria-hidden="true">↗</span></a><a class="horizon-secondary" href="studio.html"><span class="horizon-play" aria-hidden="true">✳</span>Thử một công cụ</a></div><div class="horizon-signature"><span class="horizon-line"></span><span data-exp-tagline>${E(data.config.tagline)}</span></div></div><div class="horizon-visual" id="horizon-visual"><div class="horizon-scene"><img class="horizon-scene-img" id="horizon-scene-image" src="${E(art)}" width="1920" height="1072" alt="${C.image(data.config.heroImage,400000)?'Ảnh bìa của kênh':'Vòng kim loại và kính mở ra một đường chân trời ánh sáng xanh'}" fetchpriority="high"><div class="horizon-scene-shade" aria-hidden="true"></div></div><div class="horizon-coordinate" aria-hidden="true"><span>01 / EXPLORE</span><span>GÓC NHÌN MỞ HƠN.</span></div><a class="horizon-orbit-chip chip-ai" href="chuyen-muc/${first.id}.html"><span aria-hidden="true">✳</span>${E(first.name)} <b aria-hidden="true">↗</b></a><a class="horizon-orbit-chip chip-device" href="chuyen-muc/${second.id}.html"><span aria-hidden="true">⌘</span>${E(second.name)} <b aria-hidden="true">↗</b></a><div class="horizon-art-label" aria-hidden="true">THE NEXT<br><strong>PERSPECTIVE.</strong></div><a class="horizon-lab-note" data-experience-article="${ai.id}" href="bai-viet/${ai.id}.html"><img src="assets/ai-lab-preview.png" width="140" height="79" alt="" loading="lazy"><span><small>TỪ GÓC LAB</small><strong>${E(ai.title)}</strong><b>Khám phá cẩm nang ↗</b></span></a><button class="horizon-motion" id="experience-motion" aria-pressed="false">Giảm chuyển động <span aria-hidden="true">Ⅱ</span></button></div></div><div class="container horizon-bottom"><a href="#diem-bat-dau"><span aria-hidden="true">↓</span>Cuộn để mở một góc nhìn</a><span>KHÁM PHÁ · HIỂU RÕ · ỨNG DỤNG</span><a data-experience-article="${featured.id}" href="bai-viet/${featured.id}.html">Bắt đầu với bài nổi bật <span aria-hidden="true">↗</span></a></div></section>`;}
function strip(data){return `<div class="horizon-strip"><div class="container"><span><i aria-hidden="true">✳</i>MỖI ĐIỀU BẠN TÒ MÒ, MỘT ĐIỂM BẮT ĐẦU.</span><span>${data.articles.length} CẨM NANG</span><span>${data.glossary?.length||0} THUẬT NGỮ</span><a href="studio.html">6 CÔNG CỤ THỰC HÀNH ↗</a></div></div>`;}
function recommendation(a,data,C){const E=C.escape,cat=data.categories.find(c=>c.id===a.category);return `<article class="discovery-card"><div><span class="discovery-tag">${E(cat?.short||cat?.name||'Cẩm nang')}</span><span>${a.minutes} phút</span></div><h3><a data-experience-article="${a.id}" href="bai-viet/${a.id}.html">${E(a.title)}</a></h3><p>${E(a.excerpt)}</p><a class="discovery-read" data-experience-article="${a.id}" href="bai-viet/${a.id}.html">Mở góc nhìn này <span aria-hidden="true">↗</span></a></article>`;}
function discovery(data,C,X){const E=C.escape,items=X.recommendations(data);return `<section class="container discovery-section" id="diem-bat-dau"><div class="discovery-heading"><div><span class="eyebrow">01 / THEO CÁCH BẠN TÒ MÒ</span><h2>Một điểm bắt đầu.<br><span>Đúng điều bạn muốn hiểu.</span></h2></div><p>Chọn một chủ đề và khoảng thời gian.<br>Mình cùng tìm một cẩm nang vừa vặn.</p></div><div class="discovery-controls"><div class="discovery-topics" role="group" aria-label="Chủ đề bạn quan tâm"><button class="active" data-interest="all" aria-pressed="true">Mọi góc nhìn</button>${data.categories.map(c=>`<button data-interest="${c.id}" aria-pressed="false">${E(c.short||c.name)}</button>`).join('')}</div><div class="discovery-selects"><label>Tôi muốn<select id="discovery-goal"><option value="understand">Hiểu từ đầu</option><option value="practice">Thử làm ngay</option></select></label><label>Tôi có<select id="discovery-time"><option value="3">3 phút</option><option value="5" selected>5 phút</option><option value="10">10 phút</option><option value="120">Thời gian thoải mái</option></select></label></div></div><div class="discovery-results" id="discovery-results" aria-live="polite">${items.map(a=>recommendation(a,data,C)).join('')}</div><div class="discovery-foot"><p id="discovery-status" role="status">${items.length} gợi ý theo chủ đề và thời gian bạn chọn.</p><button class="text-button" id="discovery-surprise">Cho tôi một bài bất ngờ <span aria-hidden="true">↗</span></button></div><noscript><p>Chọn <a href="tat-ca.html">tất cả cẩm nang</a> để khám phá khi JavaScript đang tắt.</p></noscript></section>`;}
function lab(data,C,X){const questions=X.labs(data);if(!questions.length)return '';const q=questions[0],E=C.escape;return `<section class="micro-lab-band" id="giai-ma-nhanh"><div class="container micro-lab-layout"><div class="micro-lab-intro"><span class="eyebrow">TH LAB / MỖI CÂU HỎI, MỘT ĐIỀU SÁNG TỎ</span><h2>Khoan đã.<br><span>Bạn có chắc?</span></h2><p>Một vài hiểu nhầm nhỏ vẫn thường gặp.<br>Chọn cách bạn nghĩ, rồi cùng mở lời giải.</p><div class="micro-orbit" aria-hidden="true"><span>?</span><i></i><b>TH</b></div></div><div class="micro-lab-card"><div class="micro-lab-top"><span id="micro-topic">${q.topic}</span><span id="micro-position">01 / ${String(questions.length).padStart(2,'0')}</span></div><h3 id="micro-question" tabindex="-1">${E(q.question)}</h3><div id="micro-answers" class="micro-answers">${q.answers.map((text,i)=>`<button data-micro-answer="${i}" aria-pressed="false"><span>${String.fromCharCode(65+i)}</span>${E(text)}<i aria-hidden="true">↗</i></button>`).join('')}</div><div class="micro-feedback" id="micro-feedback" role="status" hidden></div><div class="micro-lab-bottom"><div><label for="micro-progress" id="micro-progress-label">0 / ${questions.length} góc nhìn đã mở</label><progress id="micro-progress" value="0" max="${questions.length}"></progress></div><button class="text-button" id="micro-next">Câu tiếp theo →</button></div><noscript><p>Mở <a href="bai-viet/${q.article}.html">cẩm nang giải thích</a> để đọc đầy đủ.</p></noscript></div></div></section>`;}
const api={hero,strip,discovery,lab,recommendation};if(typeof module==='object'&&module.exports)module.exports=api;else root.THExperienceMarkup=api;
})(typeof window!=='undefined'?window:globalThis);
